Translate("esES", "alterac-mountains", {
	title = "Montañas de Alterac",
	aliases = { "Alterac", "Reino de Alterac" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Montañas de Alterac se alzan al norte de las {link:hillsbrad-foothills}Laderas de Trabalomas{/link}, una muralla de nieve y piedra gris entre las orillas del {red:lordamere-lake}Lago Lordamere{/red} y las tierras muertas de las Tierras de la Peste. En otro tiempo fueron un reino propio. Su capital yace rota en los pasos altos, y su nombre aún se pronuncia como una maldición en las cortes de los hombres, pues Alterac traicionó a la {link:alliance}Alianza{/link} en su hora más oscura. Ahora las montañas pertenecen a quien pueda conservarlas: nobles exiliados y sus matones, ogros coronados con reliquias robadas, magos, asesinos, orcos y enanos.]=],
		},
		{
			title = "Orígenes",
			text = [=[Alterac fue una de las ciudades-estado que los humanos de {link:arathor}Arathor{/link} fundaron en tierras salvajes tras la muerte del rey {link:thoradin}Thoradin{/link}, cuando su imperio creció más allá de los muros de {link:stromgarde-keep}Strom{/link}. Prosperó gracias a los caminos que cruzaban las montañas, y con el tiempo se convirtió en uno de los reinos humanos que se repartieron el antiguo imperio. La familia Perenolde lo gobernó desde un castillo en la ciudad alta. Las granjas de {link:the-uplands}Las Tierras Altas{/link} lo alimentaban, y los magos de {link:city-of-dalaran}Dalaran{/link} eran sus vecinos al otro lado del lago.]=],
		},
		{
			title = "El presente",
			text = [=[El {link:syndicate}Sindicato{/link} domina buena parte del antiguo reino. Sus señores han hecho del pueblo fantasma de {link:strahnbrad}Strahnbrad{/link} su fortaleza y de {link:the-uplands}Las Tierras Altas{/link} su coto de caza, y lord {link:lord-aliden-perenolde}Aliden Perenolde{/link} mantiene su corte en una mansión a orillas del lago. A su lado hay extraños de túnica negra. La capital en ruinas pertenece a los ogros {link:crushridge-ogres}Aplastacresta{/link} y a su señor de la guerra {link:mug-thol}Mug'thol{/link}, que lleva una corona que {link:sylvanas-windrunner}la Dama Oscura{/link} quiere recuperar. Al oeste, {link:city-of-dalaran}Dalaran{/link} se alza reconstruida, y su gran barrera ha caído. Al este, los asesinos de {link:ravenholdt-manor}Ravenholdt{/link} vigilan al Sindicato desde su mansión oculta. A la entrada del {link:alterac-valley}Valle de Alterac{/link}, enanos de {link:kingdom-of-ironforge}Forjaz{/link} y orcos del {link:frostwolf-clan}clan Lobo Gélido{/link} reúnen soldados para una guerra propia. {link:southshore}Costasur{/link} y {link:tarren-mill}Molino Tarren{/link} envían cazadores a las nieves, cada uno por sus propias razones.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}El {link:syndicate}Sindicato{/link}.{/b} Nobles caídos de Alterac, con los ladrones, salteadores y magos de las sombras que los sirven.
• {b}Los ogros {link:crushridge-ogres}Aplastacresta{/link}.{/b} Una banda de guerra ogra que ha tomado la capital en ruinas y ha excavado un túmulo en las colinas de más allá.
• {b}Los {link:the-wizards-of-ambermill}magos de Dalaran{/link}.{/b} El {link:kirin-tor}Kirin Tor{/link} y sus guardias, trabajadores y elementales atados.
• {b}La Liga de Asesinos.{/b} Los pícaros de {link:ravenholdt-manor}Ravenholdt{/link}, que no responden ante ningún rey.
• {b}La {link:stormpike-guard}Guardia de Pico Tormenta{/link} y el {link:frostwolf-clan}Clan Lobo Gélido{/link}.{/b} {link:dwarves}Enanos{/link} y orcos en guerra por el {link:alterac-valley}Valle de Alterac{/link}.
• {b}Bestias.{/b} Yetis en las cuevas, pumas de montaña en las laderas y osos en las colinas bajas.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}El reino.{/b} Durante siglos Alterac fue un reino pequeño pero orgulloso del norte, a menudo enfrentado con su vecino {link:stromgarde-keep}Stromgarde{/link}.
• {b}La {link:second-war}Segunda Guerra{/link}.{/b} El rey {link:aiden-perenolde}Aiden Perenolde{/link} dudó de la {link:alliance}Alianza{/link} desde el principio. Cuando la {link:horde}Horda{/link} llegó a sus montañas, hizo un pacto secreto con {link:orgrim-doomhammer}Orgrim Doomhammer{/link} y abrió los pasos del sur. Los orcos cruzaron en días en lugar de meses y pusieron sitio a la capital de {link:lordaeron}Lordaeron{/link}.
• {b}La caída.{/b} Cuando se conoció la traición, los ejércitos de la Alianza marcharon sobre Alterac. El rey {link:terenas-menethil}Terenas Menethil{/link} depuso a Perenolde y lo mantuvo prisionero en su propio palacio. El reino no volvió a alzarse jamás, y su pueblo se dispersó.
• {b}La peste.{/b} En la {link:third-war}Tercera Guerra{/link}, la {link:scourge}Plaga{/link} arrasó Lordaeron, y {link:archimonde}Archimonde{/link} derribó {link:city-of-dalaran}Dalaran{/link} al otro lado del lago. El poco orden que quedaba en las montañas murió con ellas.]=],
		},
		{
			title = "Tradiciones de las montañas",
			text = [=[• La Tiara de Perenolde, una reliquia familiar de la antigua casa real, la hicieron los joyeros de {link:ironforge}Forjaz{/link} y la engastaron con esmeraldas. Se perdió cuando cayó Alterac. Se dice que ahora la lleva un {link:ogres}ogro{/link} mago de los {link:crushridge-ogres}Aplastacresta{/link}.
• El magistrado de {link:southshore}Costasur{/link} fue asesinado por unos asesinos a los que nunca se encontró. Su sucesor cree que los contrató el {link:syndicate}Sindicato{/link}.
• Los cazadores dicen que un gran yeti llamado Frostmaw recorre las alturas sobre la {link:growless-cave}Caverna Estrecha{/link}.]=],
		},
	},
})

Translate("esES", "ruins-of-alterac", {
	title = "Ruinas de Alterac",
	aliases = { "Ciudad de Alterac" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Ruinas de Alterac fueron en otro tiempo la capital del reino, una ciudad amurallada en los pasos altos. Aquí celebraba su corte el rey {link:aiden-perenolde}Aiden Perenolde{/link}, y aquí dijo a sus oficiales que {link:alterac-mountains}Alterac{/link} se pondría del lado de la {link:horde}Horda{/link}. Cuando la {link:alliance}Alianza{/link} vino a por él, su pueblo huyó, y la ciudad nunca se reconstruyó. Ahora los ogros {link:crushridge-ogres}Aplastacresta{/link} dominan sus calles rotas. Su señor de la guerra {link:mug-thol}Mug'thol{/link} ha hecho su guarida en el viejo palacio, el único edificio que sigue entero. Los {link:forsaken}Renegados{/link} de {link:tarren-mill}Molino Tarren{/link} han jurado clavar su cabeza en una pica sobre estos muros.]=],
		},
	},
})

Translate("esES", "strahnbrad", {
	title = "Strahnbrad",
	sections = {
		{
			title = "Resumen",
			text = [=[Strahnbrad era un pueblo de las estribaciones orientales, en el camino entre {link:alterac-mountains}Alterac{/link} y las tierras de {link:lordaeron}Lordaeron{/link}. En vísperas de la {link:third-war}Tercera Guerra{/link}, los orcos lo asaltaron en busca de esclavos, y el príncipe {link:arthas-menethil}Arthas Menethil{/link} llegó demasiado tarde para salvar a muchos de sus habitantes. Hoy es un pueblo fantasma y el principal bastión del {link:syndicate}Sindicato{/link}. Sus señores se reúnen en sus salas vacías, y sus viejas celdas guardan a sus prisioneros. El {link:orcs}orco{/link} {link:gol-dir}Gol'dir{/link} estuvo retenido allí como esclavo, obligado a cavar y acarrear para sus captores. El magistrado de {link:southshore}Costasur{/link} quiere los anillos de sello de los nobles que se esconden entre sus ladrones.]=],
		},
	},
})

Translate("esES", "crushridge-hold", {
	title = "Dominios de los Aplastacresta",
	aliases = { "Cuenca de la Matanza", "Camino de la Horca" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Dominios de los Aplastacresta son el túmulo {link:ogres}ogro{/link} que los {link:crushridge-ogres}Aplastacresta{/link} excavaron en las colinas cercanas a la capital en ruinas. Sus cuevas y campamentos rebosan de brutos, machacadores y magos, y más adentro de las montañas tienen un segundo túmulo en la Cuenca de la Matanza. Sus patrullas vigilan el cruce de caminos del Camino de la Horca, junto a una vieja torre en ruinas. El mariscal de {link:southshore}Costasur{/link} teme el día en que los ogros se sientan lo bastante seguros para bajar a las laderas, y paga bien por cada nudillo que le traen sus cazadores.]=],
		},
	},
})

Translate("esES", "the-uplands", {
	title = "Las Tierras Altas",
	aliases = { "Tierras Altas" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Tierras Altas son las colinas altas del norte de {link:alterac-mountains}Alterac{/link}, al norte de {link:strahnbrad}Strahnbrad{/link}. Eran las tierras de cultivo del antiguo reino. Ahora son el corazón del {link:syndicate}Sindicato{/link}, que aquí es más fuerte. El barón {link:baron-vardus}Vardus{/link} tiene sus campamentos en estas colinas, y aquí aguardan también los magos de las sombras del {link:argus-wake}Argus Wake{/link}, que llegaron a Alterac como aliados del Sindicato. El magistrado de {link:southshore}Costasur{/link} envía a sus cazadores al norte, a Las Tierras Altas, cuando quiere la cabeza de un noble.]=],
		},
	},
})

Translate("esES", "dandred-s-fold", {
	title = "Redil de Dandred",
	aliases = { "Costa de la Neblina" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Redil de Dandred es una mansión con un pequeño puerto en la Costa de la Neblina, donde el oeste de {link:the-uplands}Las Tierras Altas{/link} se encuentra con el {red:lordamere-lake}Lago Lordamere{/red}. Es la casa de lord {link:lord-aliden-perenolde}Aliden Perenolde{/link}, que se llama a sí mismo señor de estas tierras. Asesinos y matones del {link:syndicate}Sindicato{/link} guardan sus puertas. En el piso de arriba vive su amante, {link:elysa}Elysa{/link}, y a su lado está {link:nagaz}Nagaz{/link}, el {link:orcs}orco{/link} que habla por {link:argus-wake}el Argus Wake{/link}. Los guerreros de {link:tarren-mill}Molino Tarren{/link} conocen el camino hasta aquí. También los cazadores de {link:southshore}Costasur{/link}.]=],
		},
	},
})

Translate("esES", "sofera-s-naze-and-corrahn-s-dagger", {
	title = "Saliente de Sofera y Daga de Corrahn",
	aliases = { "Saliente de Sofera", "Daga de Corrahn" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Saliente de Sofera y la Daga de Corrahn son dos colinas que descienden de las montañas hacia las laderas, al norte y al oeste de {link:tarren-mill}Molino Tarren{/link}. El {link:syndicate}Sindicato{/link} tiene campamentos en ambas. Desde aquí sus salteadores y ladrones bajan a robar en los caminos de {link:hillsbrad-foothills}Trabalomas{/link}, y de aquí, cree {link:southshore}Costasur{/link}, salieron los asesinos que mataron a su último magistrado. En una colina cercana a uno de estos campamentos, un secuaz del Sindicato llamado Valik yace herido, regateando por un último trago.]=],
		},
	},
})

Translate("esES", "growless-cave", {
	title = "Caverna Estrecha",
	sections = {
		{
			title = "Resumen",
			text = [=[La Caverna Estrecha se abre en las frías alturas del centro de {link:alterac-mountains}Alterac{/link}. Es una guarida de yetis de montaña, y a veces se ve cerca de su entrada a un yeti blanco llamado Skhowl. La cueva tiene también una historia más oscura. El hechicero {link:helcular}Helcular{/link}, que quiso convertirse en exánime, encendió en su interior una de sus tres piras ceremoniales: la Llama de Uzel. Su aprendiz de {link:tarren-mill}Molino Tarren{/link} aún recuerda el camino. Los cazadores dicen que quemar carne en la llama hace bajar de las cumbres al gran yeti Frostmaw.]=],
		},
	},
})

Translate("esES", "chillwind-point", {
	title = "Alto del Orvallo",
	sections = {
		{
			title = "Resumen",
			text = [=[El Alto del Orvallo es una elevación en el extremo oriental de {link:alterac-mountains}Alterac{/link}, donde un viento frío sopla por un barranco desde las Tierras de la Peste. Sobre ella se alzan las ruinas de un antiguo lugar trol, mucho más antiguo que cualquier reino humano de la región. Un ermitaño trol, {link:bath-rah-the-windwatcher}Bath'rah el Vigía del Viento{/link}, ha instalado su campamento junto al río, más abajo. Ha pasado años vigilando estas ruinas, esperando el día en que llegue un campeón capaz de enfrentarse al señor del viento que habita allí.]=],
		},
	},
})

Translate("esES", "ravenholdt-manor", {
	title = "Mansión Ravenholdt",
	aliases = { "Ravenholdt" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Mansión Ravenholdt se oculta en las colinas orientales, donde {link:alterac-mountains}Alterac{/link} se encuentra con {link:hillsbrad-foothills}Trabalomas{/link}, por encima de las ruinas de {link:durnholde-keep}Durnholde{/link}. Ningún camino conduce a ella abiertamente. Es la casa de lord {link:lord-jorach-ravenholdt}Jorach Ravenholdt{/link} y la sede de la Liga de Asesinos. Aquí se adiestra, vigila y pone a prueba a los mejores ladrones y asesinos de las tierras del norte. Los forasteros no son bienvenidos. Quienes llegan sin invitación rara vez encuentran la puerta, y quienes son invitados deben demostrar primero su astucia solo para alcanzarla. La Liga lleva años en guerra con el {link:syndicate}Sindicato{/link}.]=],
		},
	},
})

Translate("esES", "lordamere-internment-camp", {
	title = "Campo de Reclusión de Lordamere",
	sections = {
		{
			title = "Resumen",
			text = [=[El Campo de Reclusión de Lordamere se alza en una colina cerca de {link:city-of-dalaran}Dalaran{/link}. Tras la {link:second-war}Segunda Guerra{/link} fue uno de los {link:internment-camps}campos de internamiento{/link} de {link:lordaeron}Lordaeron{/link}, donde se retenía tras los muros a los orcos derrotados. Los orcos ya no están. Hoy los {link:the-wizards-of-ambermill}magos de Dalaran{/link} usan el campo como su propia prisión. Cuatro {link:forsaken}Renegados{/link} que robaron artefactos de una cámara de {link:undercity}Entrañas{/link} huyeron hasta aquí, y los magos los atraparon y los pusieron en cuarentena. La celadora {link:warden-belamoore}Belamoore{/link} guarda el campo y estudia lo que llevaban los ladrones. La Dama Oscura quiere recuperar sus artefactos.]=],
		},
	},
})

Translate("esES", "alterac-valley", {
	title = "Valle de Alterac",
	sections = {
		{
			title = "Resumen",
			text = [=[Al sur de las altas cumbres, un túnel conduce al Valle de Alterac, una tierra de hielo y pinos entre las montañas. El {link:frostwolf-clan}clan Lobo Gélido{/link} de los orcos reclama el valle como su hogar. Los enanos de la {link:stormpike-guard}Guardia de Pico Tormenta{/link} han venido a excavar en busca de reliquias y mineral, y pretenden tomar la tierra para {link:kingdom-of-ironforge}Forjaz{/link}. Fuera del túnel, ambos ejércitos tienen campamentos. Sus oficiales reciben a los nuevos soldados, los ponen a prueba y los envían al valle. La lucha en su interior nunca cesa del todo.]=],
		},
	},
})

Translate("esES", "old-dalaran-ruins", {
	title = "Old Dalaran Ruins",
	sections = {
		{
			title = "Resumen",
			text = [=[No toda {link:city-of-dalaran}Dalaran{/link} volvió a alzarse. Cuando {link:archimonde}Archimonde{/link} derribó la ciudad en la {link:third-war}Tercera Guerra{/link}, sus afueras quedaron destrozadas junto con su corazón. Los magos levantaron su nueva ciudad tras una barrera, pero las ruinas de la antigua siguen a orillas del {red:lordamere-lake}Lago Lordamere{/red}. Sus magos y elementales atados las patrullaron en otro tiempo, y los eruditos renegados creen que aún quedan tesoros de magia entre las piedras. Sin la barrera, las ruinas están abiertas a cualquiera que se atreva a registrarlas.]=],
		},
	},
})

Translate("esES", "lord-jorach-ravenholdt", {
	title = "Lord Jorach Ravenholdt",
	subtitle = "Señor de la Liga de Asesinos",
	found = "En el interior de la Mansión Ravenholdt",
	hint = [=[Encuentre al señor de la mansión oculta en las colinas orientales, si sus sirvientes le dejan entrar.]=],
	allegiance = "Liga de Asesinos · Ravenholdt",
	aliases = { "Jorach Ravenholdt", "maestro Ravenholdt" },
	sections = {
		{
			title = "Resumen",
			text = [=[Lord Jorach Ravenholdt es el amo de la {link:ravenholdt-manor}Mansión Ravenholdt{/link} y el señor de la Liga de Asesinos. Sus pícaros son los más hábiles de las tierras del norte, y no sirven a ningún rey. Es cortés con sus invitados, generoso con quienes lo sirven bien y muy reservado en sus propios asuntos. No dice lo que quiere. Simplemente pide, y espera a ver quién es lo bastante listo para conseguirlo.]=],
		},
		{
			title = "Importancia",
			text = [=[La Liga de Jorach es el enemigo más antiguo que tiene el {link:syndicate}Sindicato{/link} en {link:alterac-mountains}Alterac{/link}. Sus agentes no intentan matar a los del Sindicato uno a uno, pues son demasiados. Roban los emblemas de sus miembros, y de los deshonrados se ocupan luego los suyos. Es una guerra más silenciosa que la que libra {link:southshore}Costasur{/link}, y quizá más eficaz.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Gobierna la {link:ravenholdt-manor}Mansión Ravenholdt{/link} y a los pícaros que se adiestran allí.
• Libra una larga guerra de robo y miedo contra el {link:syndicate}Sindicato{/link}.
• Convoca a pícaros de confianza para recuperar lo que le es querido, y los recompensa con generosidad.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Jorach antes de la Liga, o de cómo llegó su casa a dominar estas colinas. Esta entrada recoge solo lo que revelan sus actos.]=],
		},
	},
	chapters = {
		{
			title = "Una simple petición",
			hint = "Responda a la llamada del señor de Ravenholdt.",
			text = [=[La llamada llegó en secreto, y Jorach recibió a su invitado con una cálida bienvenida. Había perdido algo pequeño: una bolsa azul. Los ladrones que se la llevaron ya estaban muertos. No habían logrado abrirla y la habían vendido a los {link:timbermaw-furbolgs}Fauces de Madera{/link} de {link:azshara}Azshara{/link}, que la tomaron por una reliquia sagrada. Jorach quería recuperarla, con sutileza si era posible.]=],
		},
		{
			title = "La llave azur",
			hint = "Traiga de vuelta la llave de la bolsa perdida.",
			text = [=[La bolsa estaba sellada con un encantamiento, y su llave la tenía un draco verde en el templo sumergido del {link:swamp-of-sorrows}Pantano de las Penas{/link}. Cuando le devolvieron la llave, Jorach abrió la bolsa. Una luz dorada se derramó sobre él, y abrió mucho los ojos. Lo que vio dentro, no lo dijo.]=],
		},
	},
	mentions = {
		{
			text = [=[La mansión {link:ravenholdt-manor}Ravenholdt{/link}, la invitación enviada en su nombre]=],
		},
		{ text = "Emblemas del {link:syndicate}Sindicato{/link}" },
		{ text = "Una simple petición" },
		{ text = "Bolsa azur sellada" },
		{ text = "La llave azur" },
	},
	bonds = {
		{ id = "fahrad", name = "Fahrad", note = "su gran maestro pícaro" },
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "el señor de sus enemigos" },
	},
})

Translate("esES", "fahrad", {
	title = "Fahrad",
	subtitle = "Gran maestro pícaro",
	found = "Mansión Ravenholdt",
	hint = [=[Busque al maestro pícaro que escribe las invitaciones a Ravenholdt.]=],
	allegiance = "Liga de Asesinos · Ravenholdt",
	sections = {
		{
			title = "Resumen",
			text = [=[Fahrad es el gran maestro pícaro de {link:ravenholdt-manor}Ravenholdt{/link}. Es él quien observa a los jóvenes ladrones del mundo y decide cuáles merecen ser enseñados. Sus cartas los encuentran dondequiera que estén, selladas con la marca de la mansión. Quienes acuden deben superar primero una prueba de astucia en el camino. Fahrad recibe a los supervivientes con una carcajada.]=],
		},
		{
			title = "Importancia",
			text = [=[Fahrad es la puerta de la Liga de Asesinos. Nadie entra en ella sin pasar por sus manos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Invita a {link:ravenholdt-manor}Ravenholdt{/link} a ladrones prometedores y los pone a prueba por el camino.
• Compra las cajas fuertes que sus pícaros abren en sus correrías.]=],
		},
	},
	mentions = {
		{ text = "La mansión {link:ravenholdt-manor}Ravenholdt{/link}" },
		{ text = "Se necesitan cajas de chatarra" },
	},
	bonds = {
		{ id = "lord-jorach-ravenholdt", name = "Lord Jorach Ravenholdt", note = "su amo" },
	},
})

Translate("esES", "aiden-perenolde", {
	title = "Aiden Perenolde",
	subtitle = "El rey traidor de Alterac",
	hint = [=[Conozca la historia del rey que vendió sus montañas a la Horda.]=],
	allegiance = "Reino de Alterac",
	aliases = { "rey Perenolde", "lord Aiden Perenolde" },
	sections = {
		{
			title = "Resumen",
			text = [=[Aiden Perenolde fue el último rey de {link:alterac-mountains}Alterac{/link}. Era un hombre culto y de voz suave que poseía una espada magnífica y nunca la usó. Sus rivales de la {link:alliance}Alianza{/link} lo tenían por cobarde. Él se tenía por el único rey lo bastante sabio para ver que la {link:horde}Horda{/link} no podía ser vencida. En la {link:second-war}Segunda Guerra{/link} traicionó a la Alianza para salvar su propio reino, y al hacerlo lo perdió.]=],
		},
		{
			title = "Importancia",
			text = [=[La traición de Perenolde es la razón de que {link:alterac-mountains}Alterac{/link} yazca en ruinas. Sus herederos aún sueñan con la corona que él perdió, y el {link:syndicate}Sindicato{/link} que dirigen es su amargo legado.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Se unió a la {link:alliance}Alianza de Lordaeron{/link} solo a regañadientes, y dudó de ella desde el principio.
• Atrancó los pasos de sus montañas, luego hizo un pacto secreto con {link:orgrim-doomhammer}Orgrim Doomhammer{/link} y los abrió.
• Asesinó al mensajero que trajo la llamada a las armas de {link:anduin-lothar}Lothar{/link}, y escondió el cuerpo en su castillo.
• El rey {link:terenas-menethil}Terenas{/link} lo depuso y lo confinó en su palacio de la capital en ruinas.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra cuándo ni cómo murió Aiden Perenolde. Se dice que en su cautiverio perdió el juicio. Su familia quedó bajo vigilancia, y su hijo mayor, {link:lord-aliden-perenolde}Aliden{/link}, intentó en vano limpiar su nombre.]=],
		},
	},
	chapters = {
		{
			title = "Los pasos abiertos",
			hint = "Averigüe por qué la Horda cruzó Alterac tan deprisa.",
			text = [=[Cuando la {link:horde}Horda{/link} llegó a las montañas, Perenolde envió un pájaro a su Jefe de Guerra y se reunió con él de noche. Encontró al {link:orcs}orco{/link} culto y honorable. Hicieron un tratado: la Horda pasaría sin sufrir daño, y {link:alterac-mountains}Alterac{/link} se salvaría. Perenolde llevó a sus soldados al norte y dejó vacíos los pasos del sur. Una travesía que debería haber durado meses duró dos días. Solo cuando {link:thoras-trollbane}Thoras Trollbane{/link} de {link:stromgarde-keep}Stromgarde{/link} entró en Alterac y volvió contra Perenolde a su propio general se cerraron de nuevo los pasos.]=],
		},
		{
			title = "La reliquia perdida",
			hint = "Recupere la tiara de la casa real de Alterac.",
			text = [=[Cuando cayó {link:alterac-mountains}Alterac{/link}, se perdió la Tiara de Perenolde. La habían hecho joyeros enanos, y sus esmeraldas eran las mejores que tenían. Los coleccionistas de {link:stormwind-city}Ventormenta{/link} aún la quieren. Apareció por fin en manos de un {link:ogres}ogro{/link} mago que busca tesoros en las ruinas de la misma ciudad donde el rey la llevó en otro tiempo.]=],
		},
	},
	mentions = {
		{ text = "La Tiara de Perenolde" },
		{ text = "Muertes nobles, contra los nobles de su corte caída" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "su hijo mayor" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "su aliado secreto" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "el rey que lo depuso" },
		{ id = "grel-borg-the-miser", name = "Grel'borg el Avaro", note = "tiene la tiara de su familia" },
	},
})

