	found = "Campo de Reclusión de Lordamere",
	hint = [=[Encuentre al desertor renegado retenido en el campo cercano a Dalaran.]=],
	allegiance = "Ninguna (desertor renegado)",
	aliases = { "Kegan" },
	sections = {
		{
			title = "Resumen",
			text = [=[Kegan Darkmar es uno de los cuatro {link:forsaken}Renegados{/link} que dieron la espalda a {link:undercity}Entrañas{/link}. Irrumpieron en una cámara segura de {link:sylvanas-windrunner}la Dama Oscura{/link}, robaron cuatro artefactos que necesitaban sus boticarios y huyeron a {link:city-of-dalaran}Dalaran{/link}. Los magos no les dieron la bienvenida. Pusieron a los cuatro en cuarentena en el {link:lordamere-internment-camp}Campo de Reclusión de Lordamere{/link}. Kegan y sus camaradas Ricter, Alina y Dermot esperan allí ahora, entre los magos que los retienen y los Renegados que los persiguen.]=],
		},
		{
			title = "Importancia",
			text = [=[La huida de Kegan muestra que no todos los {link:forsaken}Renegados{/link} se conforman con servir a {link:sylvanas-windrunner}la Dama Oscura{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra por qué huyeron los cuatro, ni qué esperaban encontrar en {link:city-of-dalaran}Dalaran{/link}.]=],
		},
	},
	mentions = {
		{ text = "Irrumpir en la prisión" },
	},
	bonds = {
		{ id = "warden-belamoore", name = "Celadora Belamoore", note = "su carcelera" },
		{ id = "magus-wordeen-voidglare", name = "Magus Wordeen Voidglare", note = "lo persigue" },
	},
})

