Translate("esES", "vanndar-stormpike", {
	title = "Vanndar Stormpike",
	subtitle = "General de la Guardia de Pico Tormenta",
	found = "Dun Baldar, en el norte del Valle de Alterac",
	hint = [=[Busque al general enano en su fortaleza del extremo norte del Valle de Alterac.]=],
	allegiance = "Guardia de Pico Tormenta · Reino de Forjaz",
	aliases = { "Vanndar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Vanndar Stormpike es el general de la {link:stormpike-guard}Guardia de Pico Tormenta{/link}, la expedición enana que ha entrado en el {link:alterac-valley}Valle de Alterac{/link}. Desde su fortaleza de Dun Baldar, en el norte del valle, dirige a enanos y a sus aliados de todas las razas de la {link:alliance}Alianza{/link}. Es un señor de la montaña de pocas palabras y propósito firme. El valle, promete, será suyo.]=],
		},
		{
			title = "Importancia",
			text = [=[Vanndar es la lanza de {link:kingdom-of-ironforge}Forjaz{/link} en el norte. Su expedición vino, se dice, a excavar en busca de mineral y de reliquias del pasado. Su rey le ha dado una tarea más dura: tomar los valles de {link:alterac-mountains}Alterac{/link} y conservarlos para {link:ironforge}Forjaz{/link}. Esa tarea lo ha enfrentado al {link:frostwolf-clan}clan Lobo Gélido{/link}, cuyo hogar es el valle desde que los Lobo Gélido fueron exiliados allí.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige la {link:stormpike-guard}Guardia de Pico Tormenta{/link} desde Dun Baldar.
• Hace la guerra al {link:frostwolf-clan}clan Lobo Gélido{/link} y a los trols Winterax del valle.
• Recibe a los soldados que la {link:alliance}Alianza{/link} envía al valle.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de Vanndar antes de la expedición, o de su parentesco con otros enanos que llevan el nombre Stormpike.]=],
		},
	},
	chapters = {
		{
			title = "El imperativo soberano",
			hint = "Responda a la llamada de Forjaz a los valles de Alterac.",
			text = [=[La llamada se hizo en nombre del rey {link:magni-bronzebeard}Magni Bronzebeard{/link}. Los {link:stormpike-guard}Pico Tormenta{/link} combatían a los trols por un lado y a los orcos por el otro, y necesitaban soldados. Tomar esa tierra, declararon los enanos, era derecho y deber de {link:ironforge}Forjaz{/link}. A los nuevos reclutas se les dijo que buscaran al teniente Haggerdin a las afueras del valle y comenzaran su servicio entre los Pico Tormenta.]=],
		},
		{
			title = "La batalla por Alterac",
			hint = "Enfréntese al general en Dun Baldar.",
			text = [=[Los {link:frostwolf-clan}Lobo Gélido{/link} ven el asunto de otro modo. Para ellos, los {link:stormpike-guard}Pico Tormenta{/link} son invasores. Sus guerreros pretenden abrirse paso hacia el norte por el valle hasta Dun Baldar y abatir al general en su propia fortaleza.]=],
		},
	},
	mentions = {
		{ text = "El imperativo soberano" },
		{ text = "La batalla por {link:alterac-mountains}Alterac{/link}" },
		{ text = "Campo de pruebas" },
	},
	bonds = {
		{ id = "drek-thar", name = "Drek'Thar", note = "su enemigo" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "su rey" },
		{ id = "prospector-stonehewer", name = "Prospectora Stonehewer", note = "busca reliquias para la expedición" },
	},
})

Translate("esES", "drek-thar", {
	title = "Drek'Thar",
	subtitle = "Chamán anciano del Clan Lobo Gélido",
	found = "Bastión Lobo Gélido, en el sur del Valle de Alterac",
	hint = [=[Busque al viejo chamán que gobierna desde el Bastión Lobo Gélido en el extremo sur del Valle de Alterac.]=],
	allegiance = "Clan Lobo Gélido · Horda",
	aliases = { "Drek'thar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Drek'Thar es el chamán anciano del {link:frostwolf-clan}Clan Lobo Gélido{/link} y el general de sus guerreros en el {link:alterac-valley}Valle de Alterac{/link}. Es ciego, y es viejo. Fue chamán de los Lobo Gélido en Draenor, y siguió a su pueblo al exilio en estas montañas. Hace mucho tomó a su cuidado a un joven {link:orcs}orco{/link} llamado {link:thrall}Thrall{/link} y le enseñó a hablar con los espíritus. Ahora dirige a los Lobo Gélido desde su bastión en el sur del valle.]=],
		},
		{
			title = "Importancia",
			text = [=[Drek'Thar es el maestro del Jefe de Guerra. Por él volvieron a los orcos las viejas costumbres del chamán, y por {link:thrall}Thrall{/link} volvieron a toda la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Mantuvo con vida a los {link:frostwolf-clan}Lobo Gélido{/link} en su exilio en {link:alterac-mountains}Alterac{/link}.
• Enseñó a {link:thrall}Thrall{/link} el camino del chamán y le reveló quiénes eran sus padres.
• Dirige la defensa del {link:alterac-valley}Valle de Alterac{/link} contra la {link:stormpike-guard}Guardia de Pico Tormenta{/link}.]=],
		},
	},
	chapters = {
		{
			title = "El hijo de Durotan",
			hint = "Averigüe cómo llegó el Jefe de Guerra a los Lobo Gélido.",
			text = [=[Cuando un joven {link:orcs}orco{/link} criado por humanos llegó al campamento {link:frostwolf-clan}Lobo Gélido{/link}, traía una manta rota de cuando era niño. Drek'Thar conocía sus marcas. El forastero era el hijo de Durotan, el jefe que había llevado al clan al exilio y que había sido asesinado junto con su compañera. El viejo chamán puso a prueba el orgullo y la humildad del joven orco, y luego le enseñó las costumbres de los espíritus.]=],
		},
		{
			title = "En defensa de los Lobo Gélido",
			hint = "Permanezca junto a los Lobo Gélido en su valle.",
			text = [=[Ahora han entrado enanos en el valle que dio refugio a los {link:frostwolf-clan}Lobo Gélido{/link} en sus años más oscuros. El clan querido por el Jefe de Guerra está siendo atacado, y la llamada se ha extendido por toda la {link:horde}Horda{/link}. Los guerreros son enviados al norte de {link:tarren-mill}Molino Tarren{/link}, al maestro de guerra Laggrond, que los pone a prueba a la entrada del valle antes de que combatan.]=],
		},
	},
	mentions = {
		{ text = "En defensa de los {link:frostwolf-clan}Lobo Gélido{/link}" },
		{ text = "La batalla de {link:alterac-mountains}Alterac{/link}" },
		{ text = "Campo de pruebas" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "su pupilo y Jefe de Guerra" },
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "su enemigo" },
		{ id = "voggah-deathgrip", name = "Voggah Deathgrip", note = "le envía guerreros en su ayuda" },
	},
})

Translate("esES", "crushridge-ogres", {
	title = "Ogros Aplastacresta",
	aliases = { "Aplastacresta", "ogro Aplastacresta", "clan Aplastacresta" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Aplastacresta son una banda de guerra de {link:ogres}ogros{/link} que se ha adueñado de las ruinas de la antigua capital de {link:alterac-mountains}Alterac{/link}. Brutos, machacadores, belicistas, matones y magos llenan las calles por donde cabalgaban antaño los reyes de Alterac. Han excavado un gran túmulo en las colinas cercanas y otro más adentro de las montañas, y sus patrullas vigilan el cruce de caminos hacia {link:tarren-mill}Molino Tarren{/link}.]=],
		},
		{
			title = "La Corona de la Voluntad",
			text = [=[Los Aplastacresta no vinieron a {link:alterac-mountains}Alterac{/link} por voluntad propia. Su señor de la guerra {link:mug-thol}Mug'thol{/link} estaba sometido al servicio de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, y ella envió a su banda de guerra a las montañas a recuperar una reliquia llamada la Corona de la Voluntad. Mug'thol encontró la corona y se la puso. Lo liberó del dominio de la Dama Oscura, y sus ogros lo siguieron a las ruinas como dueños de sí mismos. Tres lugartenientes, Targ, Muckrake y Glommus, están a su lado, y el {link:ogres}ogro{/link} mago {link:grel-borg-the-miser}Grel'borg{/link} busca tesoros por la ciudad.]=],
		},
		{
			title = "Enemigos por todas partes",
			text = [=[Los {link:forsaken}Renegados{/link} de {link:tarren-mill}Molino Tarren{/link} quieren la corona, y con ella las cabezas de {link:mug-thol}Mug'thol{/link} y sus lugartenientes. Los soldados de {link:southshore}Costasur{/link} temen que los ogros bajen a las laderas, y su mariscal paga una recompensa por cada {link:ogres}ogro{/link} muerto. Los ogros también han combatido al {link:syndicate}Sindicato{/link} por las ruinas del reino que ambos reclaman.]=],
		},
	},
})

Translate("esES", "argus-wake", {
	title = "Argus Wake",
	aliases = { "el Argus Wake" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Argus Wake es una orden secreta que se ha convertido en aliada del {link:syndicate}Sindicato{/link} en {link:alterac-mountains}Alterac{/link}. Sus magos de las sombras aguardan en {link:the-uplands}Las Tierras Altas{/link}, y su hierofante, el {link:orcs}orco{/link} {link:nagaz}Nagaz{/link}, está junto a lord {link:lord-aliden-perenolde}Aliden Perenolde{/link}. Los nobles de Alterac creen haber encontrado amigos poderosos. Se equivocan.]=],
		},
		{
			title = "La carta",
			text = [=[La verdad salió a la luz en una carta hallada en un campamento del {link:syndicate}Sindicato{/link}. Estaba escrita en una cifra tan rara que ni siquiera el maestro del saber de {link:southshore}Costasur{/link} pudo leerla, y hubo que llevarla a un prospector de {link:ironforge}Forjaz{/link}. {link:nagaz}Nagaz{/link} la había escrito al jefe del Wake, a quien se dirigía como su amo, designado por un consejo. El Sindicato, escribía, recuperaría {link:alterac-mountains}Alterac{/link} con la guía del Wake, y luego tomaría {link:stromgarde-keep}Stromgarde{/link}. Con una nación y una base de poder propias, el Wake prepararía entonces el camino para lo que él llamaba la Tercera Hueste. La firmó en nombre de {link:sargeras}Sargeras{/link}.]=],
		},
		{
			title = "Lo que sigue sin saberse",
			text = [=[El magistrado {link:magistrate-henry-maleb}Maleb{/link} de {link:southshore}Costasur{/link} envió cazadores tras {link:nagaz}Nagaz{/link} y sus magos. Aun así, el magistrado sabe que Nagaz era solo un sirviente. Quién dirige el Argus Wake, y hasta dónde llegan sus raíces, nadie en Costasur sabe decirlo.]=],
		},
	},
})

Translate("esES", "stormpike-guard", {
	title = "Guardia de Pico Tormenta",
	aliases = { "Expedición Pico Tormenta", "Pico Tormenta" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Guardia de Pico Tormenta es una expedición de {link:dwarves}enanos{/link} del clan Pico Tormenta en el {link:alterac-valley}Valle de Alterac{/link}, bajo el mando del general {link:vanndar-stormpike}Vanndar Stormpike{/link}. Desde su fortaleza de Dun Baldar, en el norte del valle, rastrean la tierra en busca de mineral y de reliquias de su pasado. {link:humans}Humanos{/link}, gnomos y elfos de la noche de la {link:alliance}Alianza{/link} combaten en sus filas.]=],
		},
		{
			title = "El imperativo",
			text = [=[La expedición se ha convertido en una guerra. El rey {link:magni-bronzebeard}Magni Bronzebeard{/link} ha declarado que tomar los valles de {link:alterac-mountains}Alterac{/link} es un deber del {link:kingdom-of-ironforge}Reino de Forjaz{/link}, y los Pico Tormenta luchan por reclamarlos contra los trols Winterax y los orcos del {link:frostwolf-clan}Clan Lobo Gélido{/link}. Los eruditos de la {link:explorers-league}Liga de Expedicionarios{/link} marchan con ellos, convencidos de que el valle guarda artefactos que merecen la lucha. Los orcos los llaman invasores. Los enanos dicen que el valle es suyo por derecho.]=],
		},
		{
			title = "En el presente",
			text = [=[Fuera del túnel que lleva al valle, los oficiales Pico Tormenta reciben a los soldados de la {link:alliance}Alianza{/link}, los ponen a prueba en las cavernas del valle y les entregan la insignia de la Guardia. Los carneros de los enanos, criados en la {link:amberstill-ranch}Granja de Semperámbar{/link} de {link:dun-morogh}Dun Morogh{/link}, van al norte a reforzar la expedición.]=],
		},
	},
})

Translate("esES", "frostwolf-clan", {
	title = "Clan Lobo Gélido",
	aliases = { "Lobo Gélido", "clan Lobo Gélido", "orcos Lobo Gélido" },
	sections = {
		{
			title = "Resumen",
			text = [=[El clan Lobo Gélido es un clan {link:orcs}orco{/link} que tiene su hogar en el {link:alterac-valley}Valle de Alterac{/link}. Es el clan del padre de {link:thrall}Thrall{/link}, y el Jefe de Guerra lo tiene en gran aprecio. Sus guerreros montan los grandes lobos blancos de las montañas, y su chamán anciano, {link:drek-thar}Drek'Thar{/link}, lo dirige desde el Bastión Lobo Gélido, en el sur del valle.]=],
		},
		{
			title = "El exilio",
			text = [=[En Draenor, los Lobo Gélido eran un clan orgulloso bajo su jefe, Durotan. Cuando los orcos llegaron a {link:azeroth}Azeroth{/link}, Durotan habló contra {link:gul-dan}Gul'dan{/link} y el oscuro camino que había tomado la {link:horde}Horda{/link}. Por ello, su clan fue desterrado a las {link:alterac-mountains}Montañas de Alterac{/link}. Durotan y su compañera dejaron más tarde el valle, y ambos fueron asesinados por agentes de Gul'dan. Su hijo pequeño fue hallado por un oficial humano, que lo crió como esclavo en {link:durnholde-keep}Durnholde{/link}. Los Lobo Gélido soportaron solos el frío y los largos años, y lejos de la magia vil de la Horda, sus chamanes volvieron a aprender las costumbres de los espíritus.]=],
		},
		{
			title = "El regreso del hijo",
			text = [=[Años después llegó a su campamento un joven {link:orcs}orco{/link}, huido de {link:durnholde-keep}Durnholde{/link}. Era el hijo de Durotan. {link:drek-thar}Drek'Thar{/link} le enseñó las costumbres del chamán, y desde el valle {link:thrall}Thrall{/link} partió para liberar a los orcos de los campos y construir una nueva {link:horde}Horda{/link}.]=],
		},
		{
			title = "En el presente",
			text = [=[Ahora los enanos de la {link:stormpike-guard}Guardia de Pico Tormenta{/link} han entrado en el valle. Los Lobo Gélido no entregarán su hogar, y la {link:horde}Horda{/link} ha respondido a su llamada.]=],
		},
	},
})
